import java.util.Set;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimStatus;

/** A person on a sheet: a name and their grades (A, B or C), each from a from-date, and the date they are retired from, if any;
 * and the holds they have had, each over a span of dates. */
@Entity
@Table(name = "person")
public class Person {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "name", nullable = false)
    private String name;

    /** The grades recorded, the first from the beginning of time (no from-date), the others each from a date. */
    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "person_grade", joinColumns = @JoinColumn(name = "person_id"))
    private List<DatedGrade> grades = new ArrayList<>();

    /** The person's own terms in days, or null when they have none. */
    @Column(name = "terms")
    private Integer terms;

    /** The person's contact, trimmed and lower-cased, or null when they have none. */
    @Column(name = "contact")
    private String contact;

    /** Set once retired: the person counts as retired at once, whatever the date. */
    @Column(name = "retired_from")
    private LocalDate retiredFrom;

    /** The sheet's today when the person was retired; none while not retired. */
    @Column(name = "retired_on")
    private LocalDate retiredOn;

    /** The person's past retirements, each ended by unretiring them. */
    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "person_retirement", joinColumns = @JoinColumn(name = "person_id"))
    private List<PastRetirement> pastRetirements = new ArrayList<>();

    /** The sheet's today when the person was added; none for one added before it was recorded. */
    @Column(name = "added_on")
    private LocalDate addedOn;

    /** The person's OPEN claims dated within a hold, and not bound by a statement, count in no live total. */
    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "person_hold", joinColumns = @JoinColumn(name = "person_id"))
    private List<DatedHold> holds = new ArrayList<>();

    /** The person's aliases, trimmed; each shares the names' uniqueness on the sheet. */
    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "person_alias", joinColumns = @JoinColumn(name = "person_id"))
    @Column(name = "alias", nullable = false)
    private Set<String> aliases = new HashSet<>();

    /** The person's place in the sheet's list, lowest first. */
    @Column(name = "position", nullable = false)
    private long position;

    /** The sheet the person was transferred from; null when they were not transferred in. */
    @Column(name = "origin_sheet")
    private String originSheet;

    /** Bumped on every save; an edit must carry the version it was made from. */
    @Version
    @Column(name = "version", nullable = false)
    private long version;

    protected Person() {
    }

    public Person(String sheetId, String name, String grade, LocalDate addedOn) {
        this.sheetId = sheetId;
        this.name = name;
        this.addedOn = addedOn;
        this.grades.add(new DatedGrade(null, grade, addedOn));
    }

    public Long getId() {
        return id;
    }

    public String getSheetId() {
        return sheetId;
    }

    /**
     * The person as they arrive on another sheet: their name, every grade they were given (each with
     * its from-date), their terms, contact and aliases; not their holds or retirement. They carry
     * this sheet as the one they came from.
     */
    public Person transferredTo(String toSheetId) {
        Person copy = new Person();
        copy.sheetId = toSheetId;
        copy.name = name;
        copy.addedOn = addedOn;
        grades.forEach(g -> copy.grades.add(new DatedGrade(g.getFromDate(), g.getGrade(), g.getMadeOn())));
        copy.terms = terms;
        copy.contact = contact;
        copy.aliases.addAll(aliases);
        copy.originSheet = sheetId;
        return copy;
    }

    public String getOriginSheet() {
        return originSheet;
    }

    public long getPosition() {
        return position;
    }

    public void setPosition(long position) {
        this.position = position;
    }
    public Integer getTerms() {
        return terms;
    }

    public void setTerms(Integer terms) {
        this.terms = terms;
    }

    public String getContact() {
        return contact;
    }

    public void setContact(String contact) {
        this.contact = contact;
    }

    public LocalDate getRetiredFrom() {
        return retiredFrom;
    }

    /** Retire the person from a date; {@code madeOn} is the sheet's today. */
    public void setRetiredFrom(LocalDate retiredFrom, LocalDate madeOn) {
        this.retiredFrom = retiredFrom;
        this.retiredOn = madeOn;
    }

/** Listing, adding and editing the people on a sheet. */
@RestController
@RequestMapping("/api/people")
public class PersonController {

    public record ListPeopleRequest(@NotBlank @Size(max = 100) String sheet) {
    }

    public record AddPersonRequest(@NotBlank @Size(max = 100) String sheet, @NotBlank @Size(max = 100) String user,
            @NotBlank @Size(max = 200) String name, @NotNull @Pattern(regexp = "[ABC]") String grade, @Min(0) Integer terms,
            @Size(max = 200) String contact) {
    }

    public record UpdatePersonRequest(@NotBlank @Size(max = 100) String sheet,
            @NotBlank @Size(max = 100) String user, @NotNull Long id, @NotBlank @Size(max = 200) String name,
            @NotNull @Pattern(regexp = "[ABC]") String grade, LocalDate gradeFrom, @NotNull Long version,
            @Min(0) Integer terms, @Size(max = 200) String contact) {
    }

    public record AddAliasRequest(@NotBlank @Size(max = 100) String sheet,
            @NotBlank @Size(max = 100) String user, @NotNull Long id, @NotBlank @Size(max = 200) String alias) {
    }

    public record MergePersonRequest(@NotBlank @Size(max = 100) String sheet,
            @NotBlank @Size(max = 100) String user, @NotNull Long id, @NotNull Long intoId) {
    }

    public record ImportPeopleRequest(@NotBlank @Size(max = 100) String sheet,
            @NotBlank @Size(max = 100) String user, @NotNull @Size(max = 100000) String text) {
    }

    /**
     * What an import did: how many people it added and how many it updated, and each of them as the
     * store now holds them, the added then the updated, each in line order.
     */
    public record ImportPeopleResponse(int added, int updated, List<PersonResponse> people) {
    }

    public record TransferPersonRequest(@NotBlank @Size(max = 100) String sheet,
            @NotBlank @Size(max = 100) String user, @NotNull Long id, @NotBlank @Size(max = 100) String to) {
    }
    public record RetirementResponse(LocalDate from, LocalDate to) {
    }

    /** A person, with every grade recorded for them, the one from the beginning of time first, their own terms or null, their contact or null, their aliases sorted as names are compared, and whether they clash: their name or an alias is used on another sheet of the sheet's tree, and the sheet they were transferred from or null. */
    public record PersonResponse(long id, String name, List<GradeResponse> grades, long version, boolean retired,
            LocalDate retiredFrom, boolean held, List<HoldResponse> holds, Integer terms, String contact,
            List<String> aliases, boolean clashing, String origin, List<RetirementResponse> retirements) {
    }

    public static PersonResponse response(Person person, boolean clashing) {
        List<GradeResponse> grades = person.getGrades().stream()
                .map(g -> new GradeResponse(g.getFromDate(), g.getGrade())).toList();
        return new PersonResponse(person.getId(), person.getName(), grades, person.getVersion(),
                person.isRetired(), person.getRetiredFrom(), person.isHeld(),
                person.getHolds().stream().map(h -> new HoldResponse(h.getFromDate(), h.getToDate())).toList(),
                person.getTerms(), person.getContact(), person.getAliases(), clashing, person.getOriginSheet(),
                person.getPastRetirements().stream().map(r -> new RetirementResponse(r.getFromDate(), r.getToDate())).toList());
    }

    /** The person, with whether they clash on the sheet's tree. */
    private PersonResponse response(String sheetId, Person person) {
        return response(person, service.clashing(sheetId, List.of(person)).contains(person.getId()));
    }

    /** A contact as stored: trimmed and lower-cased; null when blank. */
    private static String contact(String contact) {
        String c = contact == null ? "" : contact.trim().toLowerCase(Locale.ROOT);
        return c.isEmpty() ? null : c;
    }

    private final PersonService service;
    private final PersonMergeService merges;
    private final PersonTransferService transfers;
    private final PersonImportService imports;

    public PersonController(PersonService service, PersonMergeService merges, PersonTransferService transfers,
            PersonImportService imports) {
        this.imports = imports;
        this.service = service;
        this.merges = merges;
        this.transfers = transfers;
    }

    @PostMapping("/list")
    public List<PersonResponse> list(@Valid @RequestBody ListPeopleRequest req) {
        String sheet = req.sheet().trim();
        List<Person> people = service.list(sheet);
        Set<Long> clashing = service.clashing(sheet, people);
        return people.stream().map(p -> response(p, clashing.contains(p.getId()))).toList();
    }

    @PostMapping("/add")
    public PersonResponse add(@Valid @RequestBody AddPersonRequest req) {
        return response(req.sheet().trim(), service.add(req.sheet().trim(), req.user().trim(), req.name().trim(), req.grade(),
                req.terms(), contact(req.contact())));
    }

    @PostMapping("/import")
    public ImportPeopleResponse importPeople(@Valid @RequestBody ImportPeopleRequest req) {
        String sheet = req.sheet().trim();
        PersonImportService.Result done = imports.importPeople(sheet, req.user().trim(), req.text());
        List<Person> touched = Stream.concat(done.added().stream(), done.updated().stream()).toList();
        Set<Long> clashing = service.clashing(sheet, touched);
        return new ImportPeopleResponse(done.added().size(), done.updated().size(),
                touched.stream().map(p -> response(p, clashing.contains(p.getId()))).toList());
    }

    @PostMapping("/update")
    public PersonResponse update(@Valid @RequestBody UpdatePersonRequest req) {
        return response(req.sheet().trim(), service.update(req.sheet().trim(), req.user().trim(), req.id(), req.version(), req.name().trim(),
                req.grade(), req.gradeFrom(), req.terms(), contact(req.contact())));
    }

    @PostMapping("/aliases/add")
    public PersonResponse addAlias(@Valid @RequestBody AddAliasRequest req) {
        return response(req.sheet().trim(), service.addAlias(req.sheet().trim(), req.user().trim(), req.id(), req.alias().trim()));
    }

    /** Merge the person into another; answers the other as the store now holds them. */
    @PostMapping("/merge")
    public PersonResponse merge(@Valid @RequestBody MergePersonRequest req) {
        this.audit = audit;
        this.rollup = rollup;
    }

    @Transactional(readOnly = true)
    public List<Person> list(String sheetId) {
        return people.findBySheetIdOrderByPositionAscIdAsc(sheetId);
    }

    @Transactional
    public Person add(String sheetId, String user, String name, String grade, Integer terms) {
        return add(sheetId, user, name, grade, terms, null);
    }

    @Transactional
    public Person add(String sheetId, String user, String name, String grade, Integer terms, String contact) {
        roles.refuseViewer(sheetId, user);
        sheets.load(sheetId, user);
        RollupService.Snapshot before = rollup.snapshot(sheetId);
        if (people.existsBySheetIdAndNameIgnoreCase(sheetId, name) || people.existsAliasOnSheet(sheetId, name)
                || usedInTree(sheetId, name, null)) {
            throw nameInUse();
        }
        if (contact != null && people.existsBySheetIdAndContact(sheetId, contact)) {
            throw contactInUse();
        }
        Person person = new Person(sheetId, name, grade, sheets.today(sheetId));
        person.setTerms(terms);
        person.setContact(contact);
        person.setPosition(people.maxPosition(sheetId) + 1);
        Person added = save(person);
        audit.recordOnCommit(record("PERSON_ADDED", sheetId, user, added, sheets.today(sheetId))
                + (terms != null ? " terms=" + terms : "") + (contact != null ? " contact=" + contact : ""));
        rollup.recordChanges(sheetId, user, before);
        return added;
    }

    @Transactional
    public Person update(String sheetId, String user, long id, long version, String name, String grade,
            LocalDate gradeFrom, Integer terms, String contact) {
        roles.refuseViewer(sheetId, user);
        RollupService.Snapshot before = rollup.snapshot(sheetId);
        Person person = people.findByIdAndSheetId(id, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person on this sheet."));
        if (person.getVersion() != version) {
            throw stale();
        }
        if (people.existsBySheetIdAndNameIgnoreCaseAndIdNot(sheetId, name, id) || people.existsAliasOnSheet(sheetId, name)
                || usedInTree(sheetId, name, null)) {
            throw nameInUse();
        }
        for (String alias : person.getAliases()) {
            if (usedInTree(sheetId, alias, null)) {
                throw new ResponseStatusException(HttpStatus.CONFLICT,
                        "The alias " + alias + " is already in use on a sheet of this sheet's tree.");
            }
        }
        if (contact != null && people.existsBySheetIdAndContactAndIdNot(sheetId, contact, id)) {
            throw contactInUse();
        }
        LocalDate today = sheets.today(sheetId);
        Integer termsBefore = person.getTerms();
        String contactBefore = person.getContact();
        person.setName(name);
        person.setTerms(terms);
        person.setContact(contact);
        if (gradeFrom != null || !grade.equals(person.gradeOn(today))) {
            person.setGradeFrom(gradeFrom != null ? gradeFrom : today, grade, today);
        }
        Person saved = save(person);
        audit.recordOnCommit(record("PERSON_EDITED", sheetId, user, saved, today)
                + (Objects.equals(termsBefore, terms) ? "" : " terms=" + (terms != null ? terms : ""))
                + (Objects.equals(contactBefore, contact) ? "" : " contact=" + (contact != null ? contact : "")));
        rollup.recordChanges(sheetId, user, before);
        return saved;
    }

